 1→/**
 2→ * 统一错误码表（design.md §4.4）。
 3→ * 码段：E1xx GitHub 采集、E2xx 飞书采集、E3xx 配置与生成约束、E4xx 推送、E5xx 存储。
 4→ */
 5→export const ERROR_CODES = {
 6→  // GitHub 采集（§4.3 collectGithub 契约）
 7→  GITHUB_TOKEN_INVALID: 'SDR-E101',
 8→  GITHUB_RATE_LIMITED: 'SDR-E102',
 9→  GITHUB_TIMEOUT: 'SDR-E103',
10→  // 飞书采集（§4.3 collectFeishu 契约）
11→  FEISHU_AUTH_FAILED: 'SDR-E201',
12→  FEISHU_FIELD_MISSING: 'SDR-E202',
13→  // 配置与生成约束（§4.3 assignBlocks / renderEntry 契约）
14→  WORK_BLOCKS_INVALID: 'SDR-E301',
15→  SOURCE_LINK_MISSING: 'SDR-E302',
16→  ENV_MISSING: 'SDR-E303',
17→  // 推送（§4.3 sendMail 契约）
18→  SMTP_AUTH_FAILED: 'SDR-E401',
19→  SMTP_TIMEOUT: 'SDR-E402',
20→  // 存储（§4.4 E5xx：事务回滚后抛出）
21→  STORE_TRANSACTION_FAILED: 'SDR-E501',
22→} as const;
23→
24→export type ErrorCode = (typeof ERROR_CODES)[keyof typeof ERROR_CODES];
25→
26→export interface SdrErrorOptions {
27→  readonly source?: string;
28→  readonly cause?: unknown;
29→}
30→
31→/**
32→ * 全系统唯一错误类型（design.md §4.4）：禁止抛裸 Error。
33→ */
34→export class SdrError extends Error {
35→  readonly code: ErrorCode;
36→  readonly source: string | undefined;
37→
38→  constructor(code: ErrorCode, message: string, options: SdrErrorOptions = {}) {
39→    super(message, { cause: options.cause });
40→    this.name = 'SdrError';
41→    this.code = code;
42→    this.source = options.source;
43→  }
44→}
45→
46→/**
47→ * SdrError 码段 → CLI 统一退出码（design.md §4.2）：
48→ * E3xx 配置非法 → 9；E4xx 推送失败 → 7；其余 → 1。
49→ * 采集类（E1xx/E2xx）的部分/全部失败退出码（3/4）由 CLI 按 allSettled 结果聚合，不经此函数。
50→ */
51→export function exitCode(error: unknown): number {
52→  if (error instanceof SdrError) {
53→    if (error.code.startsWith('SDR-E3')) return 9;
54→    if (error.code.startsWith('SDR-E4')) return 7;
55→  }
56→  return 1;
57→}
58→

