 1→import { z } from 'zod';
 2→import { ERROR_CODES, SdrError } from './errors.js';
 3→
 4→/**
 5→ * 环境变量 schema（design.md §2 config 模块）。
 6→ * 全部凭证经环境变量注入，禁止写入代码与仓库（proposal §5 技术约束）。
 7→ */
 8→const envSchema = z.object({
 9→  GITHUB_TOKEN: z.string().min(1),
10→  FEISHU_APP_ID: z.string().min(1),
11→  FEISHU_APP_SECRET: z.string().min(1),
12→  SMTP_HOST: z.string().min(1),
13→  SMTP_PORT: z.coerce.number().int().positive(),
14→  SMTP_USER: z.string().min(1),
15→  SMTP_PASS: z.string().min(1),
16→  SMTP_FROM: z.string().min(1),
17→  SDR_DB_PATH: z.string().min(1).default('data/sdr.db'),
18→});
19→
20→const REQUIRED_KEYS = [
21→  'GITHUB_TOKEN',
22→  'FEISHU_APP_ID',
23→  'FEISHU_APP_SECRET',
24→  'SMTP_HOST',
25→  'SMTP_PORT',
26→  'SMTP_USER',
27→  'SMTP_PASS',
28→  'SMTP_FROM',
29→] as const;
30→
31→export interface SdrConfig {
32→  readonly github: { readonly token: string };
33→  readonly feishu: { readonly appId: string; readonly appSecret: string };
34→  readonly smtp: {
35→    readonly host: string;
36→    readonly port: number;
37→    readonly user: string;
38→    readonly pass: string;
39→    readonly from: string;
40→  };
41→  readonly dbPath: string;
42→}
43→
44→/**
45→ * 从环境变量加载并校验配置。
46→ * 缺失或非法时抛 SDR-E303（E3xx → CLI 退出码 9），错误信息包含具体变量名（T-002 验收标准）。
47→ */
48→export function loadConfig(env: Record<string, string | undefined>): SdrConfig {
49→  const missing = REQUIRED_KEYS.filter((key) => !(env[key] ?? '').trim());
50→  if (missing.length > 0) {
51→    throw new SdrError(
52→      ERROR_CODES.ENV_MISSING,
53→      `缺少必需环境变量：${missing.join('、')}`,
54→      { source: 'config' },
55→    );
56→  }
57→
58→  const parsed = envSchema.safeParse(env);
59→  if (!parsed.success) {
60→    const first = parsed.error.issues[0];
61→    const varName = first?.path.map(String).join('.') ?? '(未知变量)';
62→    throw new SdrError(
63→      ERROR_CODES.ENV_MISSING,
64→      `环境变量 ${varName} 非法：${first?.message ?? ''}`,
65→      { source: 'config' },
66→    );
67→  }
68→
69→  const e = parsed.data;
70→  return {
71→    github: { token: e.GITHUB_TOKEN },
72→    feishu: { appId: e.FEISHU_APP_ID, appSecret: e.FEISHU_APP_SECRET },
73→    smtp: {
74→      host: e.SMTP_HOST,
75→      port: e.SMTP_PORT,
76→      user: e.SMTP_USER,
77→      pass: e.SMTP_PASS,
78→      from: e.SMTP_FROM,
79→    },
80→    dbPath: e.SDR_DB_PATH,
81→  };
82→}
83→

